-- SPEC: Ràng buộc: `status` là `ISSUED|VIEWED|ACCEPTED|DECLINED|EXPIRED|WITHDRAWN`; chuyển trạng thái hợp lệ; `ACCEPTED|DECLINED` đồng bộ trạng thái đơn ứng tuyển trong cùng giao dịch; lịch sử đề nghị không sửa/xóa.
-- SPEC: Chỉ mục: `(application_id,occurred_at,id)`; `(offer_version_id,occurred_at DESC)`; 24 tháng.
CREATE TABLE IF NOT EXISTS application_offer_state_events (
    id uuid NOT NULL PRIMARY KEY,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    tenant_id uuid NOT NULL,
    application_id uuid NOT NULL,
    offer_version_id uuid NOT NULL,
    from_status varchar(24) NULL,
    to_status varchar(24) NOT NULL,
    actor_subject_id uuid NOT NULL,
    reason_code varchar(80) NOT NULL,
    trace_id varchar(64) NOT NULL
);

-- TBL-WRK-074 — job_screening_questions (source lines 1389-1395)
-- SPEC: Tập cột: `ENTITY`; chỉ sửa khi bản sửa việc làm còn `DRAFT`, bất biến sau khi gửi duyệt.
-- SPEC: Cột riêng: `tenant_id uuid NOT NULL`; `job_revision_id uuid NOT NULL` FK `job_revisions.id`; `question_type varchar(24) NOT NULL`; `prompt varchar(1000) NOT NULL`; `is_required boolean NOT NULL DEFAULT false`; `options jsonb NULL`; `validation_rule jsonb NULL`; `position integer NOT NULL`.
-- SPEC: Ràng buộc: duy nhất `(job_revision_id,position)`; `question_type` là `TEXT|SINGLE_CHOICE|MULTIPLE_CHOICE|YES_NO|NUMBER`; các lựa chọn bắt buộc đúng loại; cấm hỏi thuộc tính được bảo vệ; tổ chức khớp bản sửa.
-- SPEC: Chỉ mục: `(tenant_id,job_revision_id,position)`.
CREATE TABLE IF NOT EXISTS job_screening_questions (
    id uuid NOT NULL PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    row_version bigint NOT NULL DEFAULT 1,
    tenant_id uuid NOT NULL,
    job_revision_id uuid NOT NULL,
    question_type varchar(24) NOT NULL,
    prompt varchar(1000) NOT NULL,
    is_required boolean NOT NULL DEFAULT false,
    options jsonb NULL,
    validation_rule jsonb NULL,
    position integer NOT NULL,
    CONSTRAINT ck_job_screening_questions_row_version CHECK (row_version >= 1),
    CONSTRAINT ck_job_screening_questions_671165f7 CHECK (question_type IN ('TEXT', 'SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'YES_NO', 'NUMBER'))
);

-- TBL-WRK-075 — interview_feedback (source lines 1396-1402)
-- SPEC: Tập cột: `APPEND`.
-- SPEC: Cột riêng: `tenant_id uuid NOT NULL`; `interview_id uuid NOT NULL`; `reviewer_subject_id uuid NOT NULL`; `recommendation varchar(24) NOT NULL`; `score numeric(5,2) NULL`; `rubric_snapshot jsonb NOT NULL`; `comment text NULL`; `submitted_at timestamptz NOT NULL`; `trace_id varchar(64) NOT NULL`.
-- SPEC: Ràng buộc: duy nhất `(interview_id,reviewer_subject_id)`; `recommendation` là `STRONG_NO|NO|NEUTRAL|YES|STRONG_YES`; điểm 0–100; người duyệt là người tham gia/thành viên tổ chức còn hiệu lực; áp dụng chính sách thuộc tính được bảo vệ.
-- SPEC: Chỉ mục: `(tenant_id,interview_id,submitted_at)`; `DERIVED_SENSITIVE`, thời hạn lưu giữ như đơn ứng tuyển.
CREATE TABLE IF NOT EXISTS interview_feedback (
    id uuid NOT NULL PRIMARY KEY,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    tenant_id uuid NOT NULL,
    interview_id uuid NOT NULL,
    reviewer_subject_id uuid NOT NULL,
    recommendation varchar(24) NOT NULL,
    score numeric(5,2) NULL,
    rubric_snapshot jsonb NOT NULL,
    comment text NULL,
    submitted_at timestamptz NOT NULL,
    trace_id varchar(64) NOT NULL,
    CONSTRAINT ck_interview_feedback_d2812ff8 CHECK (recommendation IN ('STRONG_NO', 'NO', 'NEUTRAL', 'YES', 'STRONG_YES'))
);

-- TBL-WRK-076 — file_upload_sessions (source lines 1403-1409)
-- SPEC: Tập cột: `ENTITY`.
-- SPEC: Cột riêng: `file_id uuid NOT NULL UNIQUE` FK `file_objects.id`; `owner_subject_id uuid NOT NULL`; `tenant_id uuid NULL`; `upload_id varchar(200) NOT NULL UNIQUE`; `expected_size_bytes bigint NOT NULL`; `expected_sha256 char(64) NOT NULL`; `part_count integer NOT NULL DEFAULT 1`; `status varchar(24) NOT NULL DEFAULT 'CREATED'`; `expires_at timestamptz NOT NULL`; `completed_at timestamptz NULL`; `aborted_at timestamptz NULL`.
-- SPEC: Ràng buộc: kích thước >0 theo hạn mức `purpose`; số phần 1–10000; `status` là `CREATED|UPLOADING|COMPLETED|ABORTED|EXPIRED`; khi hoàn tất, kiểm kích thước/hàm băm rồi đưa ClamAV vào hàng đợi.
-- SPEC: Chỉ mục: `(owner_subject_id,status,created_at DESC)`; `(tenant_id,status,created_at DESC)`; `(status,expires_at)`; dọn sau 7 ngày kể từ trạng thái kết thúc.
CREATE TABLE IF NOT EXISTS file_upload_sessions (
    id uuid NOT NULL PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    row_version bigint NOT NULL DEFAULT 1,
    file_id uuid NOT NULL UNIQUE,
    owner_subject_id uuid NOT NULL,
    tenant_id uuid NULL,
    upload_id varchar(200) NOT NULL UNIQUE,
    expected_size_bytes bigint NOT NULL,
    expected_sha256 char(64) NOT NULL,
    part_count integer NOT NULL DEFAULT 1,
    status varchar(24) NOT NULL DEFAULT 'CREATED',
    expires_at timestamptz NOT NULL,
    completed_at timestamptz NULL,
    aborted_at timestamptz NULL,
    CONSTRAINT ck_file_upload_sessions_row_version CHECK (row_version >= 1),
    CONSTRAINT ck_file_upload_sessions_0e950315 CHECK (status IN ('CREATED', 'UPLOADING', 'COMPLETED', 'ABORTED', 'EXPIRED'))
);

